    assert.equal(c.size, 0);
  }
  // 8. TTL starts at commit
  {
    let t = 0; const g = d(); let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => (++calls, g.promise) });
    const a = c.get('k'); await tick(); t = 8; g.resolve(1); await a;
    t = 17; assert.equal(await c.get('k'), 1); t = 18; assert.equal(c.size, 0);
  }
  console.log('all scenarios ok');
})().catch(e => { console.error(e); process.exit(1); });
